    pckItem6: 'It\'s a setup from my plan, not improvised',
    pckItem7: 'I\'m not entering out of revenge or FOMO',
    pckItem8: 'I can accept losing this trade without it hurting',
    pckScore: 'Score',
    pckGoName: 'Go',
    pckGoDesc: 'It fits your plan. Execute with your normal size.',
    pckWaitName: 'Careful',
    pckWaitDesc: 'Shaky setup. Cut size or wait for a better one.',
    pckSkipName: 'Skip it',
    pckSkipDesc: 'Key conditions are missing. Skipping this is the profitable move.',
    pckReset: 'Reset',
    rdyTitle: 'Are you fit to trade today?',
    rdyIntro: 'One honest minute before the session. Answer and see your state: the market will still be there tomorrow — your account may not be, if you trade at a bad moment.',
    rdyQ1: 'I slept and rested well',
    rdyQ2: 'I\'m coming off a loss that still stings',
    rdyQ3: 'I feel the urge to win back what I lost',
    rdyQ4: 'I\'m rushed or distracted',
    rdyQ5: 'I\'ve reviewed my plan and levels today',
    rdyQ6: 'I\'m trading with money I need',
    rdyQ7: 'I feel calm and focused',
