    // Advanced Options Education
    advancedOptionsTitle: 'Advanced Options Strategies',
    advancedOptionsIntro: 'Complex multi-leg strategies for managing risk, generating income, and profiting from specific market conditions.',

    ironCondorTitle: 'Iron Condor',
    ironCondorDesc: 'Sell an OTM call + buy a further OTM call + sell an OTM put + buy a further OTM put. A four-leg strategy that profits when the underlying stays within a defined range (low volatility).',
    ironCondorMaxProfit: 'Max Profit: Net premium received',
    ironCondorMaxLoss: 'Max Loss: Width of widest spread minus net premium',
    ironCondorWhen: 'Best when: IV is high (sell premium) and underlying expected to stay in range',
    ironCondorTip: 'Tip: Manage at 50% of max profit. Close if short strikes are tested.',

    butterflySpreadTitle: 'Butterfly Spread',
    butterflySpreadDesc: 'Buy 1 ITM option + sell 2 ATM options + buy 1 OTM option. Low cost, maximum profit at the middle strike at expiry. Very precise trade.',
    butterflySpreadMaxProfit: 'Max Profit: Difference between strike widths minus net premium',
    butterflySpreadMaxLoss: 'Max Loss: Net premium paid (debit)',
    butterflySpreadWhen: 'Best when: You expect price to pin at the middle strike at expiry',
    butterflySpreadTip: 'Tip: Use near expiry (14-21 DTE) for maximum efficiency.',

    calendarSpreadTitle: 'Calendar Spread (Time Spread)',
    calendarSpreadDesc: 'Same strike, different expirations: buy longer-dated option, sell shorter-dated option. Profits from the difference in time decay rates between near and far expirations.',
    calendarSpreadMaxProfit: 'Max Profit: When near-term expires worthless and far-term retains value',
    calendarSpreadMaxLoss: 'Max Loss: Net debit paid',
    calendarSpreadWhen: 'Best when: IV is low (buy premium) and expecting IV to increase',
    calendarSpreadTip: 'Tip: IV changes affect both legs equally, but time decay works faster on the short leg.',

    diagonalSpreadTitle: 'Diagonal Spread',
    diagonalSpreadDesc: 'Different strike AND different expiration. Combines the directional bias of a vertical spread with the time decay benefit of a calendar spread. The most flexible multi-leg strategy.',
    diagonalSpreadMaxProfit: 'Max Profit: Varies — depends on direction and time decay',
    diagonalSpreadMaxLoss: 'Max Loss: Net debit paid',
    diagonalSpreadWhen: 'Best when: Mild directional bias with expectation of moderate IV changes',
    diagonalSpreadTip: 'Tip: Also called "poor man\'s covered call" (buy LEAPS, sell short-dated calls).',

    // Volatility Concepts
    volatilityConceptsTitle: 'Volatility Concepts',
    volatilityConceptsIntro: 'Understanding implied volatility is essential for options trading. IV determines the price of all options.',

    ivrTitle: 'IV Rank (IVR)',
    ivrDesc: 'Where current IV sits relative to its 52-week range. Formula: (Current IV - 52w Low) / (52w High - 52w Low) × 100. IVR above 50: sell premium. IVR below 25: buy premium.',
    ivrHigh: 'IVR > 50: Premium selling environment (Iron Condor, Covered Call)',
    ivrLow: 'IVR < 25: Premium buying environment (Debit spreads, straddles)',

    ivPercentileTitle: 'IV Percentile',
    ivPercentileDesc: 'Percentage of days in the past year when IV was below the current level. 80th percentile means IV was lower 80% of the time — historically expensive. More robust than IVR.',

    volSkewTitle: 'Volatility Skew',
    volSkewDesc: 'Difference in IV between OTM puts and OTM calls. Negative skew (put skew): OTM puts have higher IV than calls — downside protection demand. Positive skew: OTM calls more expensive than puts.',
    volSkewPut: 'Put Skew: Market fearful, downside protection in demand',
    volSkewCall: 'Call Skew: Market bullish, upside speculation demand',

    vixTitle: 'VIX — The Fear Index',
    vixDesc: 'Measures expected 30-day volatility of the S&P 500. Inverse correlation with the market: VIX rises when markets fall. VIX > 30: high fear, potential buying opportunity. VIX < 15: complacency.',
    vixHigh: 'VIX > 30: High fear — options are expensive, sell premium',
    vixLow: 'VIX < 15: Low fear — options are cheap, buy premium',

    // Greeks Deep Dive
    greeksDeepDiveTitle: 'Greeks Deep Dive',
    greeksDeepDiveIntro: 'Beyond the basics — how to use the Greeks to manage your portfolio dynamically.',

    deltaHedgingTitle: 'Delta Hedging',
    deltaHedgingDesc: 'Maintaining a delta-neutral portfolio by offsetting positive and negative deltas. If long 100 shares (delta +1.00), buy 2 ATM puts (delta ~-0.50 each) to neutralize. Requires constant rebalancing as delta changes.',
    deltaHedgingUse: 'Use when: You want to isolate theta or vega exposure without directional risk',

    gammaRiskTitle: 'Gamma Risk — The Accelerator',
    gammaRiskDesc: 'Gamma measures how fast delta changes. Near expiry, gamma explodes for ATM options — delta changes dramatically with each price move. Short gamma positions become very dangerous in the final 1-2 weeks.',
